const TOTAL_EVENTS=EVENTS.length;
let currentEra=0,currentCategory="All",markers=[],darkMode=true,currentEvent=null;
const map=new maplibregl.Map({container:"map",style:"vendor/historical-map-style.json",center:[18,23],zoom:1.55,minZoom:1,maxZoom:16,attributionControl:true});
map.addControl(new maplibregl.NavigationControl({showCompass:true}),"top-right");
const fmtYear=y=>y<0?`${Math.abs(y).toLocaleString()} BCE`:`${y} CE`;
function eraForYear(y){let i=ERAS.findIndex(e=>y>=e.min&&y<=e.max);return i<0?0:i}
function categoryColor(cat){const c=cat.toLowerCase();if(c.includes("black")||c.includes("human origins"))return "#36b66b";if(c.includes("war")||c.includes("conflict")||c.includes("genocide"))return "#9b5cff";if(c.includes("science")||c.includes("technology")||c.includes("cold war"))return "#1769ff";if(c.includes("revolution")||c.includes("law")||c.includes("government"))return "#ffeb00";if(c.includes("environment"))return "#38c7b5";if(c.includes("asia")||c.includes("trade")||c.includes("exploration"))return "#32c8c2";if(c.includes("empire")||c.includes("ancient")||c.includes("europe"))return "#e7bd58";return "#1769ff"}
function brandMapPalette(light=false){try{const layers=map.getStyle().layers||[];layers.forEach(l=>{const id=(l.id||"").toLowerCase(),src=(l["source-layer"]||"").toLowerCase(),key=id+" "+src;try{if(l.type==="background")map.setPaintProperty(l.id,"background-color",light?"#edf6fb":"#0d2f50");if(key.includes("water")||key.includes("ocean")||key.includes("sea")||key.includes("river")||key.includes("lake")){if(l.type==="fill")map.setPaintProperty(l.id,"fill-color",light?"#d9edf7":"#153e63");if(l.type==="line")map.setPaintProperty(l.id,"line-color",light?"#9ec6dc":"#346985");}else if(key.includes("sand")||key.includes("desert")){if(l.type==="fill")map.setPaintProperty(l.id,"fill-color",light?"#efdca9":"#a8782a");}else if(key.includes("forest")||key.includes("wood")||key.includes("park")||key.includes("grass")){if(l.type==="fill")map.setPaintProperty(l.id,"fill-color",light?"#cfe3d3":"#466b51");}else if(key.includes("land")||key.includes("earth")||key.includes("country")||key.includes("admin")){if(l.type==="fill")map.setPaintProperty(l.id,"fill-color",light?"#f0ead6":"#6f6133");}else if(key.includes("boundary")||key.includes("border")){if(l.type==="line")map.setPaintProperty(l.id,"line-color",light?"#5a5a5a":"#d6b95f");}}catch(_e){}})}catch(e){}}
function applyHistoricalDate(era){const y=Math.round((era.min+era.max)/2);try{if(y>0&&typeof map.filterByDate==="function")map.filterByDate(String(y))}catch(e){}}
function popupHTML(e){return `<div class="popup-year">${fmtYear(e.year)} · ${e.category}</div><div class="popup-title">${e.title}</div><div class="popup-text"><b>${e.place}</b><br>${e.text}</div><div class="popup-actions"><button onclick="window.openDeepDiveByTitle('${e.title.replace(/'/g,"\'")}')">Explore deeper</button><a href="${e.sourceUrl}" target="_blank" rel="noopener">Source ↗</a></div>`}
function worldContext(e){const i=eraForYear(e.year);const notes=["Human evolution unfolded alongside major climatic swings. The first era combines archaeology, paleoclimate, fossils, and the rise of early states.","Classical societies were connected by trade, migration, conquest, religion, and technology across Africa, Eurasia, and the Americas.","The medieval world was highly connected: African kingdoms, Islamic scholarship, Asian empires, European states, and Indian Ocean networks all shaped the period.","Oceanic exchange accelerated, empires expanded, printing and scientific inquiry spread, and the Atlantic slave trade transformed societies across continents.","Political revolutions, industrialization, abolition movements, new empires, and scientific discovery transformed everyday life and global power.","Nationalism, imperialism, mass industry, migration, African resistance, and new technologies intensified global competition.","Total war, genocide, economic crisis, mass politics, and scientific breakthroughs reshaped the twentieth century.","Decolonization, civil rights, the nuclear age, the Space Race, and competing political systems connected local struggles to global rivalry.","Globalization accelerated while apartheid, communist systems, environmental crises, digital technology, and new social movements reshaped the world.","The internet, financial integration, climate policy, terrorism, artificial intelligence, public-health crises, and social media redefined global life."];return notes[i]||notes[0]}
function detailHTML(e){const media=e.media?`<div class="detail-card"><h3>Watch inside the Explorer</h3><div class="video-wrap"><iframe src="https://www.youtube-nocookie.com/embed/${e.media.youtube}" title="${e.media.label}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><p class="note-small">${e.media.label}</p></div>`:`<div class="detail-card"><h3>Media & Learning Objects</h3><p>This event is ready for future embedded video, slides, charts, primary sources, or a mini-lesson without sending learners away from the Explorer.</p></div>`;const deck=e.mini?`<div class="detail-card"><h3>Mini Slide Deck</h3><div class="mini-deck">${e.mini.map((s,i)=>`<div class="mini-slide"><b>SLIDE ${i+1}</b><div>${s}</div></div>`).join('')}</div></div>`:'';return `<div><div class="event-image-wrap" id="eventImageWrap"><img id="eventImage" alt=""><small id="eventImageCredit">Reference image</small></div><div class="detail-facts"><div class="fact"><b>Date</b><span>${fmtYear(e.year)}</span></div><div class="fact"><b>Place</b><span>${e.place}</span></div><div class="fact"><b>Theme</b><span>${e.category}</span></div></div><div class="detail-card"><h3>What happened?</h3><p>${e.text}</p></div><div class="detail-card"><h3>Why it matters</h3><p>${e.why}</p></div><div class="detail-card"><h3>Evidence historians examine</h3><p>${e.evidence}</p></div>${deck}</div><div><div class="detail-card"><h3>World context</h3><p class="world-context">${worldContext(e)}</p></div>${media}<div class="detail-card"><h3>Continue researching</h3><p>Use the reference as a starting point, then compare multiple sources and perspectives.</p><a class="source-link" href="${e.sourceUrl}" target="_blank" rel="noopener">Open ${e.sourceName} ↗</a></div></div>`}
async function loadEventImage(e){const wrap=document.getElementById('eventImageWrap'),img=document.getElementById('eventImage'),credit=document.getElementById('eventImageCredit');if(!wrap||!img)return;try{const q=encodeURIComponent(e.title.replace(/[:]/g,' '));const r=await fetch('https://en.wikipedia.org/api/rest_v1/page/summary/'+q);if(!r.ok)throw new Error('image');const j=await r.json(),src=j.thumbnail?.source||j.originalimage?.source;if(!src)throw new Error('image');img.src=src;img.alt=e.title;credit.textContent='Reference image via Wikipedia • verify context before classroom use';wrap.classList.add('show')}catch(_e){wrap.classList.remove('show')}}function openDeepDive(e){currentEvent=e;document.getElementById('detailEyebrow').textContent=`${fmtYear(e.year)} • ${e.category}`;document.getElementById('detailTitle').textContent=e.title;document.getElementById('detailGrid').innerHTML=detailHTML(e);document.getElementById('detailModal').classList.add('show');document.getElementById('detailModal').setAttribute('aria-hidden','false');loadEventImage(e)}
window.openDeepDiveByTitle=t=>{const e=EVENTS.find(x=>x.title===t);if(e)openDeepDive(e)};
document.getElementById('detailClose').onclick=()=>{document.getElementById('detailModal').classList.remove('show')};document.getElementById('detailModal').addEventListener('click',e=>{if(e.target.id==='detailModal')document.getElementById('detailModal').classList.remove('show')});
function buildMarkers(){EVENTS.forEach(e=>{const el=document.createElement('div');el.className='history-marker';el.style.setProperty('--marker',categoryColor(e.category));const pop=new maplibregl.Popup({offset:17,maxWidth:'355px'}).setHTML(popupHTML(e));const m=new maplibregl.Marker({element:el}).setLngLat(e.coords).setPopup(pop).addTo(map);el.addEventListener('click',()=>showEvent(e));markers.push({event:e,marker:m,el})})}
function categories(){return [...new Set(EVENTS.map(e=>e.category))].sort()}
function populateFilters(){const s=document.getElementById('categoryFilter');categories().forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;s.appendChild(o)})}
function buildEraRail(){const rail=document.getElementById('eraRail');ERAS.forEach((e,i)=>{const b=document.createElement('button');b.className='era-btn';b.innerHTML=`<b>${i+1}. ${e.label}</b>${e.range}`;b.onclick=()=>selectEra(i,true);rail.appendChild(b)})}
function eventMatches(e){const era=ERAS[currentEra];return e.year>=era.min&&e.year<=era.max&&(currentCategory==='All'||e.category===currentCategory)}
function updateMarkers(){let n=0;markers.forEach(o=>{const yes=eventMatches(o.event);o.el.style.display=yes?'block':'none';if(yes)n++});document.getElementById('visibleCount').textContent=n;return n}
function clearSource(){document.getElementById('sourceRow').classList.remove('show');currentEvent=null}
function selectEra(i,fly){currentEra=Math.max(0,Math.min(ERAS.length-1,Number(i)));const era=ERAS[currentEra];document.getElementById('eraSlider').value=currentEra;document.getElementById('eraNow').textContent=era.label;document.getElementById('eraRange').textContent=era.range;document.querySelectorAll('.era-btn').forEach((b,j)=>b.classList.toggle('active',j===currentEra));const n=updateMarkers();document.getElementById('eventSummary').textContent=currentCategory==='All'?`${n} curated turning points from ${era.range}.`:`${n} ${currentCategory} event${n===1?'':'s'} in ${era.range}.`;document.getElementById('cardEyebrow').textContent=`Era ${currentEra+1} of 10 • ${era.range}`;document.getElementById('cardTitle').textContent=era.label;document.getElementById('cardScript').textContent=currentCategory==='All'?'Explore people, environments, conflicts, ideas, science, and change.':`Filtered view: ${currentCategory}`;document.getElementById('cardText').textContent=n?`Click a colored marker for a concise explanation, then open the Deep Dive for context, evidence, and media where available. Search across all ${TOTAL_EVENTS} curated events.`:'No events in this era match the current filter. Choose another category or era.';clearSource();applyHistoricalDate(era);if(fly)map.flyTo({center:era.center,zoom:era.zoom,duration:900})}
function showEvent(e){const i=eraForYear(e.year);if(i!==currentEra){currentEra=i;document.getElementById('eraSlider').value=i;document.querySelectorAll('.era-btn').forEach((b,j)=>b.classList.toggle('active',j===i))}document.getElementById('cardEyebrow').textContent=`${fmtYear(e.year)} • ${e.category}`;document.getElementById('cardTitle').textContent=e.title;document.getElementById('cardScript').textContent=e.place;document.getElementById('cardText').textContent=e.text;const row=document.getElementById('sourceRow'),link=document.getElementById('sourceLink'),name=document.getElementById('sourceName');link.href=e.sourceUrl;link.textContent=`Read ${e.sourceName} ↗`;name.textContent='Reference link';row.classList.add('show');currentEvent=e;document.getElementById('deepBtn').onclick=()=>openDeepDive(e);updateMarkers();map.flyTo({center:e.coords,zoom:Math.max(map.getZoom(),4.3),duration:850})}
function doSearch(){const q=document.getElementById('searchInput').value.trim().toLowerCase(),box=document.getElementById('results');if(!q){box.style.display='none';return}const hits=EVENTS.filter(e=>`${e.title} ${e.place} ${e.category} ${e.text} ${e.year}`.toLowerCase().includes(q)).slice(0,28);box.innerHTML=hits.length?hits.map(e=>`<div class="result" data-i="${EVENTS.indexOf(e)}"><strong>${e.title}</strong><span><em>${fmtYear(e.year)}</em> • ${e.place} • ${e.category}</span></div>`).join(''):`<div class="result"><strong>No curated match yet</strong><span>Try Africa, Black History, human origins, Civil War, climate, universe, revolution, China, technology, empire, or rights.</span></div>`;box.style.display='block';box.querySelectorAll('.result[data-i]').forEach(r=>r.onclick=()=>{const e=EVENTS[Number(r.dataset.i)];currentCategory='All';document.getElementById('categoryFilter').value='All';box.style.display='none';showEvent(e)})}
function surprise(){const choices=EVENTS.filter(eventMatches);if(choices.length)showEvent(choices[Math.floor(Math.random()*choices.length)])}
document.getElementById('searchBtn').onclick=doSearch;document.getElementById('searchInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();doSearch()}});document.getElementById('searchInput').addEventListener('input',()=>{if(document.getElementById('searchInput').value.length>=3)doSearch();else document.getElementById('results').style.display='none'});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))document.getElementById('results').style.display='none'});
document.getElementById('categoryFilter').onchange=e=>{currentCategory=e.target.value;selectEra(currentEra,false)};document.getElementById('eraSlider').oninput=e=>selectEra(e.target.value,true);document.getElementById('prevBtn').onclick=()=>selectEra((currentEra+9)%10,true);document.getElementById('nextBtn').onclick=()=>selectEra((currentEra+1)%10,true);document.getElementById('randomBtn').onclick=surprise;document.getElementById('resetBtn').onclick=()=>{currentCategory='All';document.getElementById('categoryFilter').value='All';document.getElementById('searchInput').value='';map.flyTo({center:[18,23],zoom:1.55,duration:900});selectEra(0,false)};
document.getElementById('themeBtn').onclick=()=>{darkMode=!darkMode;document.querySelector('.map-tint').style.opacity=darkMode?'1':'.28';document.getElementById('themeBtn').textContent=darkMode?'Historic Tint: On':'Historic Tint: Soft';if(window.ETPTransitions?.clickSound)window.ETPTransitions.clickSound('map')};
document.getElementById('signupForm').addEventListener('submit',e=>{e.preventDefault();const mail=document.getElementById('signupEmail').value.trim();if(mail)location.href=`mailto:examinethepast@gmail.com?subject=${encodeURIComponent('World History Explorer Updates')}&body=${encodeURIComponent('Please add '+mail+' to World History Explorer updates.')}`});
function share(type){const u=encodeURIComponent(location.href),txt=encodeURIComponent('Explore world history with the Examine the Past World History Explorer');let url='';if(type==='facebook')url=`https://www.facebook.com/sharer/sharer.php?u=${u}`;if(type==='x')url=`https://twitter.com/intent/tweet?url=${u}&text=${txt}`;if(type==='linkedin')url=`https://www.linkedin.com/sharing/share-offsite/?url=${u}`;if(type==='pinterest')url=`https://www.pinterest.com/pin/create/button/?url=${u}&description=${txt}`;if(type==='email')url=`mailto:?subject=${encodeURIComponent('World History Explorer')}&body=${txt}%0A%0A${u}`;if(type==='copy'){navigator.clipboard?.writeText(location.href);alert('Link copied.');return}window.open(url,'_blank','noopener')}document.querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>share(b.dataset.share));
populateFilters();buildEraRail();selectEra(0,false);map.on('load',()=>{brandMapPalette(false);buildMarkers();selectEra(currentEra,false);document.getElementById('mapStatus')?.remove()});window.addEventListener('pageshow',()=>map.resize());window.addEventListener('pagehide',()=>{map.stop();document.querySelectorAll('.detail-modal iframe').forEach(f=>f.src='')});
